WITH observations AS (SELECT * FROM (SELECT dataset_id,event_uuid,event_name,occurred_at,visitor_id,session_id,pathname,device,product_id,variant_id,landing_pathname,referrer_host,discovery_source,discovery_channel,discovery_campaign,discovery_placement,session_source,session_channel,session_campaign,session_placement,result_count,concept_kind,concept_id FROM (SELECT *,row_number() OVER (PARTITION BY dataset_id,event_uuid ORDER BY occurred_at) AS observation_rank FROM (SELECT dataset_id,toString(event_uuid) AS event_uuid,event_name,occurred_at,visitor_id,toString(session_id) AS session_id,pathname,device,toString(product_id) AS product_id,toString(variant_id) AS variant_id,landing_pathname,referrer_host,discovery_source,discovery_channel,discovery_campaign,discovery_placement,session_source,session_channel,session_campaign,session_placement,result_count,concept_kind,toString(concept_id) AS concept_id FROM (SELECT 'sole-staging' AS dataset_id, uuid AS event_uuid, event AS event_name,
 timestamp AS occurred_at, distinct_id AS visitor_id, properties.$session_id AS session_id, properties.pathname AS pathname,
 if(properties.device IN ('desktop','mobile','tablet','unknown'),properties.device,NULL) AS device,
 if(event IN ('product_viewed','product_added_to_cart','out_of_stock_viewed','variant_selected','unavailable_size_requested'),properties.product_id,NULL) AS product_id,
 if(event IN ('product_added_to_cart','variant_selected','unavailable_size_requested'),properties.variant_id,NULL) AS variant_id,
 if(event='catalog_search_results',toInt(properties.result_count),NULL) AS result_count,
 if(event='catalog_search_results' AND properties.concept_kind IN ('brand','model','product') AND match(properties.concept_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),properties.concept_kind,NULL) AS concept_kind, if(event='catalog_search_results' AND properties.concept_kind IN ('brand','model','product') AND match(properties.concept_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),properties.concept_id,NULL) AS concept_id,
 if(match(properties.landing_pathname,'^(/|/(store|cart|checkout|hours|brands|contact|authenticity-guarantee|privacy|terms|refunds|shipping|legal/(privacy|terms|shipping|refunds))|/store/[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$'),properties.landing_pathname,NULL) AS landing_pathname,
 if(length(properties.referrer_host)<=253 AND match(properties.referrer_host,'^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?[.])+[a-z]{2,24}$') AND NOT match(properties.referrer_host,'([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'),properties.referrer_host,NULL) AS referrer_host,
 if(match(properties.discovery_source, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.discovery_source, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.discovery_source, NULL) AS discovery_source,
 if(match(properties.discovery_channel, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.discovery_channel, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.discovery_channel, NULL) AS discovery_channel,
 if(match(properties.discovery_campaign, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.discovery_campaign, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.discovery_campaign, NULL) AS discovery_campaign,
 if(match(properties.discovery_placement, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.discovery_placement, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.discovery_placement, NULL) AS discovery_placement,
 if(match(properties.session_source, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.session_source, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.session_source, NULL) AS session_source,
 if(match(properties.session_channel, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.session_channel, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.session_channel, NULL) AS session_channel,
 if(match(properties.session_campaign, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.session_campaign, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.session_campaign, NULL) AS session_campaign,
 if(match(properties.session_placement, '^[a-z0-9][a-z0-9_-]{0,63}$') AND NOT match(properties.session_placement, '([a-z0-9]{24,}|token|secret|password|auth|session|key|([0-9][ _-]?){7})'), properties.session_placement, NULL) AS session_placement
 FROM events
 WHERE timestamp >= parseDateTimeBestEffort('2026-11-27T18:00:00Z','UTC')
 AND timestamp >= parseDateTimeBestEffort({variables.start_inclusive},'UTC') AND timestamp < parseDateTimeBestEffort({variables.end_exclusive},'UTC')
 AND properties.environment='staging' AND properties.storefront='sole' AND properties.schema_version=2
 AND match(distinct_id,'^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|sole-buyer:v1:[0-9a-f]{64})$') AND match(properties.$session_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') AND match(properties.pathname,'^(/|/(store|cart|checkout|hours|brands|contact|authenticity-guarantee|privacy|terms|refunds|shipping|legal/(privacy|terms|shipping|refunds))|/store/[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$')
 AND (event='public_page_viewed' OR (event='storefront_viewed' AND properties.pathname='/store')
 OR (event='checkout_started' AND properties.pathname='/checkout')
 OR (event='catalog_search_results' AND match(toString(properties.result_count),'^(0|[1-9][0-9]{0,9})$') AND toInt(properties.result_count)<=2147483647)
 OR (event IN ('product_viewed','product_added_to_cart','out_of_stock_viewed','variant_selected','unavailable_size_requested') AND match(properties.product_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') AND properties.pathname=concat('/store/',properties.product_id)
 AND (event NOT IN ('product_added_to_cart','variant_selected','unavailable_size_requested') OR match(properties.variant_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) AND (event!='product_added_to_cart' OR properties.quantity=1)))))) WHERE observation_rank=1) WHERE {variables.behavior_enabled}='yes' AND occurred_at<parseDateTimeBestEffort({variables.behavior_end},'UTC') ),
 observed AS (
 SELECT h.*,CASE WHEN p.distinct_id=h.visitor_id THEN concat('person:',toString(p.person_id)) ELSE concat('distinct:',h.visitor_id) END AS visitor,
 UUIDv7ToDateTime(toUUID(toString(h.session_id))) AS entered_at
 FROM observations h LEFT JOIN person_distinct_ids p ON h.visitor_id=p.distinct_id
 ), valid_events AS (
 SELECT * FROM observed WHERE substring(toString(session_id),15,1)='7' AND occurred_at>=entered_at AND occurred_at<addHours(entered_at,24)
 ), session_events AS (
 SELECT *,row_number() OVER (PARTITION BY session_id ORDER BY occurred_at,event_uuid) AS entry_rank,
 row_number() OVER (PARTITION BY session_id ORDER BY occurred_at DESC,event_uuid DESC) AS last_rank
 FROM valid_events WHERE entered_at >= parseDateTimeBestEffort({variables.start_inclusive},'UTC') AND entered_at < parseDateTimeBestEffort({variables.end_exclusive},'UTC') AND entered_at>=parseDateTimeBestEffort({variables.activated_at},'UTC')
 ), session_entries AS (
 SELECT e.*,latest_session_event.visitor AS session_visitor FROM session_events e
 JOIN session_events latest_session_event ON latest_session_event.session_id=e.session_id AND latest_session_event.last_rank=1 WHERE e.entry_rank=1
 ) SELECT count(DISTINCT visitor) AS visitors,(SELECT count(*) FROM observed WHERE NOT (substring(toString(session_id),15,1)='7' AND occurred_at>=entered_at AND occurred_at<addHours(entered_at,24)) AND ({variables.device}='' OR coalesce(nullIf(device,''),'unknown')={variables.device}) AND ({variables.source}='' OR coalesce(nullIf(session_source,''),'unknown')={variables.source}) AND ({variables.channel}='' OR coalesce(nullIf(session_channel,''),'unknown')={variables.channel}) AND ({variables.campaign}='' OR coalesce(nullIf(session_campaign,''),'unknown')={variables.campaign})) AS invalid_events FROM valid_events WHERE ({variables.device}='' OR coalesce(nullIf(device,''),'unknown')={variables.device}) AND ({variables.source}='' OR coalesce(nullIf(session_source,''),'unknown')={variables.source}) AND ({variables.channel}='' OR coalesce(nullIf(session_channel,''),'unknown')={variables.channel}) AND ({variables.campaign}='' OR coalesce(nullIf(session_campaign,''),'unknown')={variables.campaign})